        change(e.sheetId(), e.user(), "CLAIM_DEFERRED sheet=" + e.sheetId() + " by=" + e.user()
                + " person=" + e.person() + " amount=" + e.amount().setScale(2, RoundingMode.HALF_UP).toPlainString()
                + " date=" + e.date() + (e.number() == null ? "" : " number=" + e.number())
                + " until=" + e.until());
    }

    @TransactionalEventListener
    public void on(ClaimReminded e) {
        change(e.sheetId(), e.user(), "REMIND sheet=" + e.sheetId() + " by=" + e.user()
                + " person=" + e.person() + " amount=" + e.amount().setScale(2, RoundingMode.HALF_UP).toPlainString()
                + " date=" + e.date() + (e.number() == null ? "" : " number=" + e.number()));
    }

    @TransactionalEventListener
    public void on(ClaimProofAdded e) {
        change(e.sheetId(), e.user(), "CLAIM_PROOF_ADDED sheet=" + e.sheetId() + " by=" + e.user()
                + " person=" + e.person() + " amount=" + e.amount().setScale(2, RoundingMode.HALF_UP).toPlainString()
                + " date=" + e.date() + (e.number() == null ? "" : " number=" + e.number())
                + " proofs=" + e.proofs());
    }

    @TransactionalEventListener
    public void on(ClaimLineAdded e) {
        change(e.sheetId(), e.user(), "CLAIM_LINE_ADDED sheet=" + e.sheetId() + " by=" + e.user()
                + " person=" + e.person() + " amount=" + e.amount().setScale(2, RoundingMode.HALF_UP).toPlainString()
                + " date=" + e.date() + (e.number() == null ? "" : " number=" + e.number())
                + " label=" + e.label() + " qty=" + e.qty() + " unit=" + e.unit().toPlainString());
    }

    @TransactionalEventListener
    public void on(ClaimCommented e) {
        change(e.sheetId(), e.user(), "COMMENT_ADDED sheet=" + e.sheetId() + " by=" + e.user()
                + " person=" + e.person() + " amount=" + e.amount().setScale(2, RoundingMode.HALF_UP).toPlainString()
                + " date=" + e.date() + (e.number() == null ? "" : " number=" + e.number())
